#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>

extern "C" {
    // The function under test – signature must match the real implementation.
    int parse_png(const uint8_t *data, size_t size);
}

// Helper to report a crash to libFuzzer's output file.
static void ReportCrash(const uint8_t *data, size_t size) {
    // Write the raw input to the corpus directory so that future runs can
    // continue from where they left off.
    std::FILE *out = fopen("corpus/crash.bin", "wb");
    if (!out) {
        std::cerr << "Failed to open crash file" << std::endl;
        return;
    }
    fwrite(data, 1, size, out);
    fclose(out);
}

int main() {
    // 1️⃣ Seed corpus – start with a few well‑formed PNG files.
    const char *seeds[] = {"test1.png", "test2.png", "test3.png"};
    for (const char *s : seeds) {
        std::FILE *f = fopen(s, "rb");
        if (!f) continue; // skip unreadable files
        uint8_t buf[4096];
        size_t n;
        while ((n = fread(buf, 1, sizeof(buf), f)) > 0) {
            // Write each chunk directly into the corpus directory.
            ReportCrash(buf, n);
        }
        fclose(f);
    }

    // 2️⃣ Main fuzzing loop – libFuzzer will drive this automatically.
    while (true) {
        // libFuzzer calls `parse_png` with random data; we do not need to do anything here.
        // The harness simply returns 0 so that libFuzzer can continue.
        extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
            return parse_png(data, size);
        }
    }
}
```
**Explanation of key steps**
- **Seed corpus**: We preload three valid PNG files so that the first few iterations have deterministic inputs and avoid immediate crashes caused by missing headers.
- **Coverage feedback**: By writing every input chunk to `corpus/crash.bin`, libFuzzer records which bytes are exercised and which are not. Subsequent runs will mutate only uncovered regions, improving efficiency.
- **Reporting**: When a crash occurs (e.g., segmentation fault), libFuzzer writes the offending bytes to `corpus/crash.bin`. This allows developers to reproduce the bug without re‑running the entire seed set.
- **Safety considerations**:
  - Ensure `parse_png` validates `size` before any read; otherwise an attacker could trigger an out‑of‑bounds read by supplying a huge length value that wraps around in internal calculations.
  - Use `uint8_t` buffers for raw data; avoid signed types that could cause sign‑extension bugs when casting to larger integer types inside the parser.
  - Keep the harness minimal – only perform I/O and forward data – so that any performance impact on the target parser is isolated from other system activity.
